import{test}from'node:test';import assert from'node:assert/strict';import{readFileSync as read}from'node:fs';import{execFileSync}from'node:child_process';import{createHash}from'node:crypto';
import{availableChapterCollections,chapterHash,parseChapterHash,selectedChapterCollection,displayedChapterCollections,chapterExerciseChoices}from'../lib/practice-chapters.ts';import{importedItems,importedExercise}from'../lib/imported-practice.ts';import{gradeContentResponse,importedItemIssues}from'../lib/imported-practice-contract.ts';import{wordRoundDefinitions}from'../lib/word-rounds.ts';import{sortIssues}from'../docs/word-coverage-release-20261031/check-sort.mjs';
const base='d6246bf96c0aea01e230d5ef576fe0365f368b9c',levels=['alfa-a','alfa-b','alfa-c','a1','a2','b1'],banks=JSON.parse(read('docs/word-coverage-release-20261031/banks.json')),uses=JSON.parse(read('data/klink-word-use-self.json'));const tasks=c=>c.contentUrl?JSON.parse(read('public'+c.contentUrl)).exercises:c.exercises,sha=b=>createHash('sha256').update(b).digest('hex');
test('Twenty missing combinations populated, source teacher choices and Alfa synonym exclusion retained',()=>{let gaps=0;for(const level of levels)for(const activity of['word-sort','same-word','hear-word','content-woordpakketten']){const cs=availableChapterCollections(activity,{level,help:'practice'});assert(cs.length&&cs.flatMap(tasks).length);if(!['same-word','hear-word'].includes(activity)||!['alfa-a','alfa-b'].includes(level))gaps++;}assert.equal(gaps,20);for(const level of levels.slice(0,3))assert.equal(availableChapterCollections('synonyms',{level,help:'practice'}).length,0);for(const[level,n]of levels.map((l,i)=>[l,[664,318,18,24,24,12][i]]))assert.equal(availableChapterCollections('content-woordpakketten',{level,help:'guided'}).flatMap(tasks).length,n);});
test('604 complete sorting boards each have exactly one correct category per word',()=>{let count=0;for(const b of banks.filter(x=>x.activity==='word-sort'))for(const e of tasks({contentUrl:b.url})){assert.deepEqual(sortIssues(e),[]);assert.equal(new Set(e.standardTask.items.map(i=>i.categoryId)).size,2);assert.equal(e.access,'self-practice');assert.equal(e.independentReading,false);count++;}assert.equal(count,604);});
test('Both new search forms have identical target sets and valid answers/audio, in balanced short rounds',()=>{for(const level of levels.slice(2)){const same=banks.filter(b=>b.level===level&&b.activity==='same-word'),hear=banks.filter(b=>b.level===level&&b.activity==='hear-word'),ss=same.flatMap(b=>tasks({contentUrl:b.url})),hs=hear.flatMap(b=>tasks({contentUrl:b.url}));assert.deepEqual(ss.map(e=>e.wordId),hs.map(e=>e.wordId));for(const [i,s]of ss.entries()){const h=hs[i];assert.equal(s.exampleWord,s.options.find(o=>o.id===s.answer.correctOptionIds[0]).label);assert.equal(s.requiresAudio,false);assert(!s.prompt.audio);assert(h.requiresAudio&&h.prompt.audio.src);assert.equal(new Set(s.options.map(o=>o.label)).size,s.options.length);assert.equal(h.answer.correctOptionIds.length,1);}for(const bank of[...same,...hear]){const rs=wordRoundDefinitions(tasks({contentUrl:bank.url}));assert(rs.length);assert.equal(rs.flatMap(r=>r.exerciseIds).length,bank.count);assert(rs.every(r=>r.wordIds.length<=8));}}});
test('All 42 context questions reject every distractor and have separate IDs and no teacher scoring',()=>{for(const item of uses){assert.deepEqual(importedItemIssues(item),[]);assert.equal(gradeContentResponse(item,[]).correct,false);for(const opt of item.options)assert.equal(gradeContentResponse(item,[opt.id]).correct,opt.id==='good',item.id);const e=importedExercise(item);assert.equal(e.access,'self-practice');assert.equal(e.independentReading,false);assert.equal(e.assessment,'answer');assert(!e.contentTask.teacherWorkflow&&!e.contentTask.teacherReference);assert(!/Voorbeeld voor de oefenfase|Nieuwe situatie:/.test(item.stimulus));assert(!importedItems.find(x=>x.id===item.id.slice('self-use:'.length)).id.startsWith('self-use:'));}});
test('All original source data, production rows and published exercise bytes unchanged',()=>{assert.equal(sha(read('data/klink-imported-practice.json')),sha(execFileSync('git',['show',base+':data/klink-imported-practice.json'],{maxBuffer:30e6})));const prior=JSON.parse(execFileSync('git',['show',base+':data/klink-production-index.json'],{maxBuffer:10e6})),now=JSON.parse(read('data/klink-production-index.json'));assert.deepEqual(now.filter(r=>!r.id.startsWith('word-self:')),prior);const ids=new Set(banks.flatMap(b=>b.exerciseIds));assert.equal(ids.size,banks.reduce((n,b)=>n+b.count,0));for(const r of prior)assert(!tasks({contentUrl:r.url}).some(e=>ids.has(e.exerciseId)));});
test('Short round deep links retain target words between new search forms and reload',()=>{for(const level of levels.slice(2)){const c=displayedChapterCollections('same-word',{level,help:'practice'}).find(c=>c.id.startsWith('word-self:'));assert(c?.wordRound);const loc={chapter:'words',activity:'same-word',collection:c.id,words:c.wordRound.wordIds,level,help:'practice'};assert.deepEqual(selectedChapterCollection(parseChapterHash(chapterHash(loc))).wordRound.wordIds,c.wordRound.wordIds);const choices=chapterExerciseChoices(loc);assert(choices.some(c=>c.id==='hear-word'));assert(choices.some(c=>c.id==='listen'));}});

test('Closed Alfa context questions link only their actual target, not the old contrast word',()=>{for(const item of uses.filter(i=>['Alfa A','Alfa B'].includes(i.level))){assert.deepEqual(importedExercise(item).targetWordIds,['klink-woord-'+item.options.find(o=>o.id==='good').text]);assert(item.sourceIds.includes(item.id.slice('self-use:'.length)));}});
